import time

from merging import merge_all


def test_later_keys_win():
    assert merge_all([{"a": 1, "b": 1}, {"b": 2}, {"c": 3}]) == {"a": 1, "b": 2, "c": 3}


def test_empty_list():
    assert merge_all([]) == {}


def test_single_dict_unchanged():
    assert merge_all([{"x": 1}]) == {"x": 1}


def test_inputs_not_mutated():
    d1, d2 = {"a": 1}, {"b": 2}
    merge_all([d1, d2])
    assert d1 == {"a": 1}
    assert d2 == {"b": 2}


def test_performance_many_dicts():
    n = 60000
    dicts = [{f"k{i}": i} for i in range(n)]

    start = time.perf_counter()
    got = merge_all(dicts)
    elapsed = time.perf_counter() - start

    assert len(got) == n
    assert got["k0"] == 0 and got[f"k{n - 1}"] == n - 1
    # calibrated: {**acc, **d} rebuilds the whole dict every iteration -
    # measured ~4.1s at n=60000 growing keys vs ~0.003s for acc.update(d) -
    # a >1000x gap, so this stays a reliable discriminator across hardware
    # speeds rather than sitting close to the naive path's own runtime (n
    # was doubled from an earlier n=30000/1.2s budget after that margin
    # turned out too tight on faster-than-originally-assumed hardware).
    assert elapsed < 2.0, (
        f"merge_all took {elapsed:.2f}s for {n} dicts; expected acc.update(d) "
        f"in the loop, not acc = {{**acc, **d}} which copies the whole "
        f"accumulator every iteration"
    )

